{
  "name": "Mission 1 - Contract Data Source",
  "description": "Reshapes raw sales order fields into template-ready Customer fields.",
  "variables": "[]",
  "loadMethod": "Storage"
}

{
  "name": "Mission 1 - World Industries Contract Solution",
  "description": "Ties the Data Source to the World Industries contract template.",
  "dataGuid": "{{mission1.dataSourceId}}"
}

{
  "envelope": {
    "subject": "Please sign: World Industries Contract — Customer A"
  },
  "recipients": [
    {
      "templateRole": "Customer",
      "name": "{{mission3.customerAName}}",
      "email": "{{mission3.customerAEmail}}"
    }
  ]
}
